import type { BankQuestion } from "@/lib/bank";

/** Laws of Motion and Friction (Physics (JEE/NEET)): 128 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"phy-laws-of-motion-1","question":"Newton's first law of motion is also known as the law of:","options":["inertia","action and reaction","conservation of momentum","gravitation"],"answer":0,"explanation":"The first law states that a body keeps its state of rest or uniform motion unless acted on by a net external force — the property of inertia. Action–reaction is the third law.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-laws-of-motion-2","question":"A net force of 10 N acts on a body of mass 2 kg. The acceleration produced is:","options":["20 m/s²","5 m/s²","0.2 m/s²","12 m/s²"],"answer":1,"explanation":"a = F/m = 10/2 = 5 m/s².","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-laws-of-motion-3","question":"The working of a rocket is based on the principle of:","options":["Newton's first law","conservation of energy","Archimedes' principle","conservation of linear momentum"],"answer":3,"explanation":"Exhaust gases are ejected backward with momentum, so the rocket gains equal forward momentum (Newton's third law / momentum conservation); no external medium is needed to push against.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-laws-of-motion-4","question":"A 50 kg person stands on a weighing machine in a lift accelerating upward at 2 m/s² (g = 10 m/s²). The reading of the machine is:","options":["500 N","400 N","700 N","600 N"],"answer":3,"explanation":"N − mg = ma gives N = m(g + a) = 50 × 12 = 600 N. The reading would be 400 N if the lift accelerated downward at 2 m/s².","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-laws-of-motion-5","question":"A block placed on an inclined plane just begins to slide when the angle of the incline is raised to 30°. The coefficient of static friction is:","options":["1/√3","√3","1/2","√3/2"],"answer":0,"explanation":"At the angle of repose mg sinθ = μ mg cosθ, so μ = tanθ = tan30° = 1/√3 ≈ 0.58.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-laws-of-motion-6","question":"A 0.2 kg ball moving at 10 m/s strikes a wall normally and rebounds with the same speed. The magnitude of the impulse given to the ball is:","options":["0","2 N s","4 N s","1 N s"],"answer":2,"explanation":"Impulse = change in momentum = m(v − (−v)) = 0.2 × (10 + 10) = 4 N s. Taking the velocities as equal and getting zero ignores the reversal of direction.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-laws-of-motion-7","question":"Masses of 3 kg and 2 kg hang from the two ends of a light string over a frictionless, massless pulley (g = 10 m/s²). The tension in the string is:","options":["20 N","30 N","24 N","25 N"],"answer":2,"explanation":"a = (m₁ − m₂)g/(m₁ + m₂) = 10/5 = 2 m/s². For the 2 kg mass, T − 20 = 2 × 2, so T = 24 N (the same from the 3 kg side: 30 − 3 × 2 = 24 N).","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-laws-of-motion-8","question":"A car takes a turn of radius 20 m on a level road where the coefficient of friction between the tyres and road is 0.5 (g = 10 m/s²). The maximum speed at which it can turn without skidding is:","options":["10 m/s","20 m/s","5 m/s","14 m/s"],"answer":0,"explanation":"Friction supplies the centripetal force: mv²/r ≤ μmg, so vₘₐₓ = √(μrg) = √(0.5 × 20 × 10) = √100 = 10 m/s.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-laws-of-motion-9","question":"The maximum value of static friction between two dry surfaces depends on the:","options":["area of contact","speed of the body","normal reaction between the surfaces","volume of the body"],"answer":2,"explanation":"Limiting friction fₘₐₓ = μₛN is proportional to the normal reaction and independent of the apparent area of contact (for the same materials).","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-laws-of-motion-10","question":"Two blocks of 2 kg and 3 kg are in contact on a frictionless table. A horizontal force of 10 N is applied to the 2 kg block. The contact force between the blocks is:","options":["4 N","6 N","10 N","5 N"],"answer":1,"explanation":"a = 10/5 = 2 m/s² for the system. The only horizontal force on the 3 kg block is the contact force, so N = 3 × 2 = 6 N. (If the 10 N were applied to the 3 kg block instead, the contact force would be 4 N.)","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-laws-of-motion-11","question":"A block slides down a 30° incline with coefficient of kinetic friction 1/(2√3) (g = 10 m/s²). Its acceleration is:","options":["5 m/s²","2.5 m/s²","7.5 m/s²","1.25 m/s²"],"answer":1,"explanation":"a = g sinθ − μg cosθ = 10 × 0.5 − (1/(2√3)) × 10 × (√3/2) = 5 − 2.5 = 2.5 m/s².","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-laws-of-motion-12","question":"A simple pendulum hangs from the roof of a car accelerating horizontally at 10 m/s² (g = 10 m/s²). In the steady state the string makes an angle with the vertical of:","options":["45°","60°","30°","0°"],"answer":0,"explanation":"In the car frame a pseudo force ma acts backward; equilibrium gives tanθ = a/g = 1, so θ = 45°.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-laws-of-motion-13","question":"Blocks of 1 kg, 2 kg and 3 kg are connected in that order by light strings on a frictionless table and pulled by a 12 N force applied to the 3 kg block. The tension in the string between the 2 kg and 3 kg blocks is:","options":["6 N","2 N","4 N","12 N"],"answer":0,"explanation":"a = 12/6 = 2 m/s². The string between the 2 kg and 3 kg blocks pulls the 1 kg + 2 kg combination, so T = 3 × 2 = 6 N; the other string carries 1 × 2 = 2 N.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-laws-of-motion-14","question":"A 40 kg monkey climbs a rope that can bear a maximum tension of 600 N (g = 10 m/s²). The maximum acceleration with which it can climb upward without breaking the rope is:","options":["15 m/s²","10 m/s²","2.5 m/s²","5 m/s²"],"answer":3,"explanation":"T − mg = ma, so 600 − 400 = 40a and a = 5 m/s². Climbing at constant speed needs only 400 N.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-laws-of-motion-15","question":"A road is banked at an angle θ with tanθ = 0.2 on a curve of radius 50 m (g = 10 m/s²). The speed at which a vehicle can take the turn with no friction needed is:","options":["20 m/s","5 m/s","25 m/s","10 m/s"],"answer":3,"explanation":"Without friction, the horizontal component of the normal reaction provides the centripetal force: tanθ = v²/rg, so v = √(rg tanθ) = √(50 × 10 × 0.2) = 10 m/s.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-laws-of-motion-16","question":"Sand falls vertically onto a horizontal conveyor belt at 2 kg/s. To keep the belt moving at a constant 3 m/s, the extra force required is:","options":["3 N","9 N","6 N","1.5 N"],"answer":2,"explanation":"F = v dm/dt = 3 × 2 = 6 N, since each second 2 kg of sand must be given a horizontal momentum of 3 kg m/s. (The power needed is Fv = 18 W, twice the kinetic energy given to the sand per second.)","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-laws-of-motion-17","question":"A 2 kg block rests on a horizontal surface with μₛ = 0.6 and μₖ = 0.5 (g = 10 m/s²). A horizontal force of 10 N is applied. The friction force acting on the block is:","options":["12 N","10 N","20 N","0"],"answer":1,"explanation":"Limiting friction = μₛmg = 12 N exceeds the applied 10 N, so the block stays at rest and static friction adjusts itself to exactly 10 N. Friction equals μₛN only when the block is on the verge of sliding.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-laws-of-motion-18","question":"A stone tied to a string of length 2 m is whirled in a vertical circle (g = 10 m/s²). The minimum speed at the lowest point for it to complete the circle is:","options":["√20 m/s","5 m/s","20 m/s","10 m/s"],"answer":3,"explanation":"At the top the string just slackens when v = √(gr) = √20 m/s; energy conservation to the bottom gives vₘᵢₙ = √(5gr) = √100 = 10 m/s.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-laws-of-motion-19","question":"A 2 kg block rests on top of a 4 kg block that lies on a frictionless floor. The coefficient of friction between the blocks is 0.5 (g = 10 m/s²). The maximum horizontal force that can be applied to the lower block so that the two move together is:","options":["15 N","20 N","60 N","30 N"],"answer":3,"explanation":"The upper block is driven only by friction, so its acceleration cannot exceed μg = 5 m/s². The system then needs F = (2 + 4) × 5 = 30 N. (If the force were applied to the upper block instead, the limit would be 15 N.)","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-laws-of-motion-20","question":"How many of the following statements about friction are correct?\n(A) Static friction can be smaller than μₛN.\n(B) Friction always opposes the motion of the body on which it acts.\n(C) Kinetic friction is usually slightly less than the limiting static friction.\n(D) The coefficient of friction can never exceed 1.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"(A) and (C) are correct. (B) is false — friction opposes relative motion (or its tendency) and can drive a body, as on the upper block of an accelerating stack or when walking. (D) is false — μ > 1 is possible (e.g. rubber on rubber).","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-laws-of-motion-21","question":"A 4 kg block on a frictionless 30° incline is connected by a string over a smooth pulley at the top to a 4 kg mass hanging freely (g = 10 m/s²). The tension in the string is:","options":["20 N","30 N","40 N","25 N"],"answer":1,"explanation":"Driving force = 40 − 40 sin30° = 20 N on a total mass of 8 kg, so a = 2.5 m/s². For the hanging mass, 40 − T = 4 × 2.5, giving T = 30 N.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-laws-of-motion-22","question":"A 2 kg block rests on the smooth face of a wedge inclined at 60°. The wedge is pushed horizontally so that the block stays at rest relative to the wedge (g = 10 m/s²). The acceleration of the wedge is:","options":["10/√3 m/s²","10 m/s²","10√3 m/s²","20 m/s²"],"answer":2,"explanation":"In the wedge frame the pseudo force ma must balance along the incline: ma cosθ = mg sinθ, so a = g tanθ = 10 × √3 = 10√3 m/s². The normal force is then mg/cosθ = 40 N.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-laws-of-motion-23","question":"A 60 kg man stands on a weighing scale in a lift that is moving upward but slowing down at 2 m/s² (g = 10 m/s²). The scale reads:","options":["720 N","480 N","600 N","0"],"answer":1,"explanation":"Moving up while slowing down means the acceleration is 2 m/s² downward, so N = m(g − a) = 60 × 8 = 480 N. The direction of motion is irrelevant; only the acceleration matters.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-laws-of-motion-24","question":"A 3 kg block hangs from the lower end of a uniform rope of mass 2 kg. The upper end of the rope is pulled so that the whole system accelerates upward at 2 m/s² (g = 10 m/s²). The tension at the midpoint of the rope is:","options":["40 N","48 N","60 N","36 N"],"answer":1,"explanation":"Below the midpoint there is the block plus half the rope, 4 kg. T − 4 × 10 = 4 × 2 gives T = 48 N. (The tension at the top end is 5 × 12 = 60 N.)","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-laws-of-motion-25","question":"A 0.5 kg stone is whirled in a vertical circle on a string (g = 10 m/s²). The difference between the tension at the lowest point and at the highest point is:","options":["10 N","20 N","depends on the speed","30 N"],"answer":3,"explanation":"T_low − T_high = (mv_low²/r + mg) − (mv_high²/r − mg); with v_low² − v_high² = 4gr from energy conservation this equals 6mg = 6 × 0.5 × 10 = 30 N, independent of the speed.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-laws-of-motion-26","question":"Assertion (A): Newton's second law in the form F = ma can be applied directly, without modification, in the frame of a uniformly accelerating car.\nReason (R): In a non-inertial frame a pseudo force −ma must be added to the real forces.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"An accelerating car is a non-inertial frame, so Newton's laws hold there only after adding the pseudo force −ma on each body; hence A is false and R is true.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-laws-of-motion-27","question":"A 1 kg block lies on a rough horizontal surface (μ = 0.2, g = 10 m/s²). A horizontal force F = 2t newton (t in seconds) is applied from t = 0. The velocity of the block at t = 3 s is:","options":["4 m/s","3 m/s","9 m/s","6 m/s"],"answer":0,"explanation":"The block starts moving when 2t = μmg = 2 N, i.e. at t = 1 s. After that, dv/dt = 2t − 2, so v(3) = ∫₁³ (2t − 2) dt = [t² − 2t]₁³ = 3 − (−1) = 4 m/s.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-laws-of-motion-28","question":"A 2 kg block on a horizontal table (μ = 0.5) is connected by a string over a smooth pulley to a 3 kg block hanging vertically (g = 10 m/s²). The tension in the string is:","options":["20 N","12 N","18 N","30 N"],"answer":2,"explanation":"Net driving force = 30 − μ × 20 = 20 N on 5 kg, so a = 4 m/s². For the hanging block: 30 − T = 3 × 4, T = 18 N.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-laws-of-motion-29","question":"A cyclist rides at 10 m/s around a curve of radius 10√3 m (g = 10 m/s²). To stay balanced the cyclist must lean from the vertical by:","options":["45°","30°","60°","15°"],"answer":1,"explanation":"tanθ = v²/rg = 100/(10√3 × 10) = 1/√3, so θ = 30° from the vertical.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-laws-of-motion-30","question":"How many of the following statements are correct?\n(A) Newton's first law gives a way of identifying inertial frames.\n(B) Action and reaction forces act on the same body.\n(C) The impulse of a force equals the change in momentum it produces.\n(D) The total momentum of a system is conserved only when the net external force on it is zero.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(A), (C) and (D) are correct. (B) is false — action and reaction act on different bodies, which is why they never cancel each other.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-laws-of-motion-31","question":"The inertia of a body depends on its:","options":["mass","velocity","volume","shape"],"answer":0,"explanation":"Inertia, the resistance to a change in the state of rest or motion, is measured by mass alone; a fast and a slow body of the same mass have the same inertia.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-laws-of-motion-32","question":"A force of 10 N acts for 0.2 s on a 0.5 kg ball initially at rest. The speed of the ball afterwards is:","options":["1 m/s","0.4 m/s","2 m/s","4 m/s"],"answer":3,"explanation":"Impulse = FΔt = 10 × 0.2 = 2 N s = mv, so v = 2/0.5 = 4 m/s.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-laws-of-motion-33","question":"A 5 kg gun fires a 50 g bullet at 200 m/s. The recoil speed of the gun is:","options":["0.2 m/s","20 m/s","2 m/s","1 m/s"],"answer":2,"explanation":"Total momentum stays zero: 0.05 × 200 = 5 × V, so V = 10/5 = 2 m/s.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-laws-of-motion-34","question":"A 2 kg block is pressed against a vertical wall by a horizontal force F. If the coefficient of static friction is 0.5 (g = 10 m/s²), the minimum F that keeps the block from sliding down is:","options":["20 N","80 N","40 N","10 N"],"answer":2,"explanation":"The normal reaction equals F, and friction μF must support the weight: 0.5F = 20 N, so F = 40 N.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-laws-of-motion-35","question":"A 10 kg block rests on a horizontal floor with μ = 0.75 (g = 10 m/s²). The minimum force that can just move it, applied at a suitable angle above the horizontal, is:","options":["60 N","45 N","75 N","100 N"],"answer":0,"explanation":"Pulling at θ: F(cosθ + μ sinθ) = μmg, smallest when tanθ = μ (θ = 37°). Then F_min = μmg/√(1 + μ²) = 75/1.25 = 60 N, less than the 75 N needed for a horizontal pull.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-laws-of-motion-36","question":"A small bob tied to a 1 m string moves in a horizontal circle as a conical pendulum, with the string at 60° to the vertical (g = 10 m/s²). The period of revolution is about:","options":["2.8 s","1.4 s","2.0 s","1.0 s"],"answer":1,"explanation":"T cosθ = mg and T sinθ = mω²L sinθ give ω² = g/(L cosθ). Period = 2π√(L cosθ/g) = 2π√(0.5/10) = 2π × 0.224 ≈ 1.4 s.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-laws-of-motion-37","question":"Masses of 3 kg and 1 kg hang from a light string over a light frictionless pulley. The pulley is pulled upward with an acceleration of 2 m/s² (g = 10 m/s²). The tension in the string is:","options":["12 N","24 N","18 N","15 N"],"answer":2,"explanation":"In the pulley's frame the effective gravity is g + a = 12 m/s². T = 2m₁m₂g_eff/(m₁ + m₂) = 2 × 3 × 1 × 12/4 = 18 N. Using g alone gives 15 N.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-laws-of-motion-38","question":"A body initially at rest is acted on by a force F = (6t − 2t²) N, with t in seconds. Its momentum at t = 3 s is:","options":["9 kg m/s","18 kg m/s","27 kg m/s","zero"],"answer":0,"explanation":"p = ∫F dt = 3t² − (2/3)t³; at t = 3 s, p = 27 − 18 = 9 kg m/s. The force itself is zero at t = 3 s, but the momentum built up earlier remains.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-laws-of-motion-39","question":"A 2 kg block rests on a rough 30° incline with μ = 1/(2√3) (g = 10 m/s²). The ratio of the maximum to the minimum force, applied parallel to the incline, that keeps the block at rest is:","options":["1.5","3","4","2"],"answer":1,"explanation":"mg sin30° = 10 N and μmg cos30° = (1/2√3) × 20 × (√3/2) = 5 N. Minimum force = 10 − 5 = 5 N (friction helps), maximum = 10 + 5 = 15 N (friction opposes). Ratio = 3.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-laws-of-motion-40","question":"A 1 kg block rests on a 3 kg block lying on a frictionless floor. The coefficient of friction between the blocks is 0.3 (g = 10 m/s²). A horizontal force of 20 N is applied to the lower block. The acceleration of the upper block is:","options":["4 m/s²","5 m/s²","5.67 m/s²","3 m/s²"],"answer":3,"explanation":"Together they would need a = 20/4 = 5 m/s², but friction can give the top block at most μg = 3 m/s², so they slip. The upper block moves at 3 m/s² and the lower at (20 − 3)/3 ≈ 5.67 m/s².","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-laws-of-motion-41","question":"Block A of mass m hangs from the ceiling by a light spring, and block B of mass 2m hangs from A by a light string. The string is suddenly cut. Immediately afterwards, the accelerations of A and B are:","options":["3g upward and g downward","g upward and g downward","zero and g downward","2g upward and g downward"],"answer":3,"explanation":"Before cutting, the spring force is 3mg. A spring cannot change length instantly, so on A: 3mg − mg = ma → a = 2g upward. B is now in free fall, g downward.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-laws-of-motion-42","question":"A curve of radius 90 m is banked at an angle θ with tanθ = 1/2, and the coefficient of friction between the tyres and the road is 1/3 (g = 10 m/s²). The maximum safe speed on the curve is:","options":["17.3 m/s","30 m/s","36 m/s","21.2 m/s"],"answer":1,"explanation":"v²max = rg(tanθ + μ)/(1 − μ tanθ) = 90 × 10 × (5/6)/(5/6) = 900, so v = 30 m/s. 21.2 m/s is the no-friction speed √(rg tanθ), and 17.3 m/s uses friction alone on a level road.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-laws-of-motion-43","question":"How many of the following statements are correct?\n(A) A cricketer moves his hands back while catching a ball to reduce the force by increasing the time of impact.\n(B) Impulse equals the change in momentum.\n(C) Internal forces can change the total momentum of a system.\n(D) A body in uniform circular motion has constant momentum.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"A and B are correct. C is wrong: internal forces cancel in pairs (Newton's third law). D is wrong: the direction of momentum keeps changing. So only two are correct.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-laws-of-motion-44","question":"A 5 kg block on a rough 37° incline (μ = 0.5) is connected by a string over a smooth pulley at the top to a freely hanging mass m (g = 10 m/s², sin37° = 0.6). The value of m for which the block moves up the incline at constant velocity is:","options":["3 kg","5 kg","4 kg","1 kg"],"answer":1,"explanation":"Moving up, friction acts down the slope: mg = Mg(sin37° + μ cos37°) = 50(0.6 + 0.4) = 50 N, so m = 5 kg. 1 kg is the mass for steady motion down the slope (friction reversed: 50 × 0.2 = 10 N).","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-laws-of-motion-45","question":"A uniform chain lies on a rough horizontal table with part of it hanging over the edge. If the coefficient of friction is 0.25, the maximum fraction of the chain's length that can hang without the chain slipping is:","options":["33%","25%","20%","80%"],"answer":2,"explanation":"With a fraction f hanging, fmg = μ(1 − f)mg → f = μ/(1 + μ) = 0.25/1.25 = 0.2, i.e. 20%. Taking f = μ = 25% forgets that only the part on the table presses on it.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id": "phy-laws-of-motion-46", "question": "A car moves along a straight level road at a constant velocity of 20 m/s. The net force acting on it is:", "options": ["equal to the engine's driving force", "equal to its weight", "zero", "directed along the motion and constant"], "answer": 2, "explanation": "Constant velocity means zero acceleration, so by Newton's second law the net force is zero: the driving force exactly balances friction and air drag.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-laws-of-motion-47", "question": "The SI unit of impulse is the same as the SI unit of:", "options": ["linear momentum", "force", "work", "power"], "answer": 0, "explanation": "Impulse = F × Δt = Δp, so its unit N s equals kg m/s, the unit of momentum. It is not a force; it is a force multiplied by a time.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-laws-of-motion-48", "question": "A force on a 2 kg body at rest increases uniformly from 0 to 20 N in 4 s. The speed of the body at the end of the 4 s is:", "options": ["40 m/s", "10 m/s", "80 m/s", "20 m/s"], "answer": 3, "explanation": "Impulse = area under the F–t graph = ½ × 4 × 20 = 40 N s = Δp, so v = 40/2 = 20 m/s. 40 m/s uses the full 20 N for 4 s.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "phy-laws-of-motion-49", "question": "A 2 kg ball tied to a string moves in a horizontal circle of radius 0.5 m on a smooth table at a constant speed of 2 m/s. The tension in the string is:", "options": ["8 N", "16 N", "4 N", "20 N"], "answer": 1, "explanation": "The tension supplies the centripetal force: T = mv²/r = 2 × 4/0.5 = 16 N. The table's normal reaction balances the weight, so gravity plays no part here.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-laws-of-motion-50", "question": "A machine gun fires 10 bullets per second, each of mass 20 g, at 500 m/s. The average force needed to hold the gun steady is:", "options": ["1000 N", "100 N", "10 N", "50 N"], "answer": 1, "explanation": "Force = rate of change of momentum = n m v = 10 × 0.02 × 500 = 100 N.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-laws-of-motion-51", "question": "A 10 kg mass hangs from the midpoint of a light string whose ends are fixed so that each half makes 30° with the horizontal (g = 10 m/s²). The tension in each half is:", "options": ["50 N", "57.7 N", "200 N", "100 N"], "answer": 3, "explanation": "Vertical balance: 2T sin 30° = 100 N, so T = 100 N. 57.7 N comes from using cos 30°, i.e. measuring the angle from the vertical.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "phy-laws-of-motion-52", "question": "A 5 kg block on a smooth horizontal floor is pulled by a 20 N force directed 30° above the horizontal (g = 10 m/s²). The normal reaction of the floor on it is:", "options": ["40 N", "50 N", "60 N", "32.7 N"], "answer": 0, "explanation": "The upward component 20 sin 30° = 10 N partly supports the block, so N = 50 − 10 = 40 N. Pushing downward at the same angle would give 60 N.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-laws-of-motion-53", "question": "A uniform rope of length 2 m lies on a smooth horizontal table and is pulled at one end by a horizontal force of 10 N. The tension in the rope at a point 0.5 m from the pulled end is:", "options": ["2.5 N", "10 N", "7.5 N", "5 N"], "answer": 2, "explanation": "The tension at distance x from the pulled end only accelerates the remaining (L − x)/L of the rope: T = F(1 − x/L) = 10 × (1 − 0.25) = 7.5 N. 2.5 N is the fraction of rope in front of the point, not behind it.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-laws-of-motion-54", "question": "A 2 kg ball falls onto a floor at 10 m/s and rebounds at 5 m/s, the contact lasting 0.1 s (g = 10 m/s²). The average force exerted by the floor on the ball is:", "options": ["300 N", "100 N", "280 N", "320 N"], "answer": 3, "explanation": "Δp = 2 × (10 + 5) = 30 N s upward, so the net average force is 300 N up. The floor must also balance the weight: N = 300 + 20 = 320 N. 300 N forgets gravity during contact; 100 N ignores the reversal of direction.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-laws-of-motion-55", "question": "A 10 kg box rests on a floor with coefficient of friction 0.5 (g = 10 m/s², sin 37° = 0.6). The minimum force needed to just move it when the force is a push directed 37° below the horizontal is:", "options": ["45.5 N", "100 N", "62.5 N", "50 N"], "answer": 1, "explanation": "Pushing down raises the normal reaction: F cos 37° = 0.5(100 + F sin 37°), so 0.8F = 50 + 0.3F and F = 100 N. Pulling 37° above the horizontal needs only 50/1.1 ≈ 45.5 N, which is why pulling is easier.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-laws-of-motion-56", "question": "A 1000 kg car crosses a convex bridge whose top is a circular arc of radius 40 m. At the top its speed is 10 m/s (g = 10 m/s²). The normal reaction of the bridge on the car there is:", "options": ["12500 N", "10000 N", "7500 N", "2500 N"], "answer": 2, "explanation": "At the top mg − N = mv²/R, so N = 1000(10 − 100/40) = 7500 N. 12500 N is the reading for a concave dip, where N exceeds mg.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "phy-laws-of-motion-57", "question": "Blocks of 2 kg and 3 kg on a horizontal floor are joined by a light string. The 3 kg block is pulled by a horizontal force of 20 N, and the coefficient of kinetic friction is 0.1 for both blocks (g = 10 m/s²). The tension in the string is:", "options": ["8 N", "6 N", "12 N", "10 N"], "answer": 0, "explanation": "a = (20 − 0.1 × 50)/5 = 3 m/s². For the 2 kg block, T − 0.1 × 20 = 2 × 3, so T = 8 N. 6 N forgets the friction on the trailing block.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-laws-of-motion-58", "question": "A rocket of mass 1000 kg ejects gas at 500 m/s relative to itself. The rate at which it must eject gas to rise vertically from the launch pad with an initial acceleration of 10 m/s² is (g = 10 m/s²):", "options": ["20 kg/s", "10 kg/s", "40 kg/s", "80 kg/s"], "answer": 2, "explanation": "Thrust u(dm/dt) must give m(g + a) = 1000 × 20 = 20000 N, so dm/dt = 20000/500 = 40 kg/s. 20 kg/s ignores the weight that the thrust must also overcome.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-laws-of-motion-59", "question": "A box lies on the floor of a truck, 4 m from its open rear end. The coefficient of friction (static and kinetic) between box and floor is 0.3. The truck starts from rest with acceleration 4 m/s² (g = 10 m/s²). The box falls off after:", "options": ["2√2 s ≈ 2.8 s", "√2 s ≈ 1.4 s", "2 s", "4 s"], "answer": 0, "explanation": "Friction can give the box at most 3 m/s², so it slides back relative to the truck with 4 − 3 = 1 m/s². Then ½ × 1 × t² = 4 m gives t = 2√2 ≈ 2.8 s.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-laws-of-motion-60", "question": "Block A (4 kg) lies on a smooth horizontal table. A light string from A passes over a fixed pulley at the table's edge, goes down around a light movable pulley carrying block B (4 kg), and its end is tied to a fixed hook directly below the fixed pulley. The acceleration of B is (g = 10 m/s²):", "options": ["4 m/s²", "5 m/s²", "10/3 m/s²", "2 m/s²"], "answer": 3, "explanation": "String constraint: a_B = a_A/2. For A: T = 4a_A. For B: 40 − 2T = 4 × a_A/2. So 40 − 8a_A = 2a_A, a_A = 4 m/s² and a_B = 2 m/s² (T = 16 N). 5 m/s² treats the pulley as fixed.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "phy-laws-of-motion-61", "question": "A block is projected at 10 m/s up a rough incline of 37° (μ = 0.5 for both static and kinetic friction; sin 37° = 0.6, g = 10 m/s²). Its speed when it returns to the starting point is:", "options": ["10 m/s", "2√5 m/s ≈ 4.5 m/s", "5 m/s", "it does not come back"], "answer": 1, "explanation": "Up: retardation 10(0.6 + 0.4) = 10 m/s², so it goes 5 m. Since tan 37° = 0.75 > 0.5 it slides back, with a = 10(0.6 − 0.4) = 2 m/s²: v² = 2 × 2 × 5 = 20, v = 2√5 m/s.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-laws-of-motion-62", "question": "How many of the following statements about Newton's third law are correct?\n(A) Action and reaction act on different bodies.\n(B) Action and reaction cancel each other, so a body can never accelerate.\n(C) For a book resting on a table, the normal force of the table on the book is the reaction to the book's weight.\n(D) The law holds for non-contact forces such as gravity as well as for contact forces.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "A and D are correct. B is wrong because the pair acts on different bodies and cannot cancel. C is wrong: the reaction to the book's weight is the book's gravitational pull on the Earth; the normal force pairs with the book's push on the table. Two are correct.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-laws-of-motion-63", "question": "A 1 kg block is held against the vertical front face of a 10 kg cart only by friction (μ = 0.5 between block and cart) while a horizontal force pushes the cart from behind along a smooth floor (g = 10 m/s²). The minimum force needed to keep the block from slipping down is:", "options": ["200 N", "220 N", "22 N", "110 N"], "answer": 1, "explanation": "The cart's face pushes the block with N = ma, and friction μN must hold up mg: a ≥ g/μ = 20 m/s². The whole system then needs F = (10 + 1) × 20 = 220 N. 200 N forgets to accelerate the block itself.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-laws-of-motion-64", "question": "A 2 kg block rests on an incline whose angle can be changed; the coefficient of friction (static and kinetic) is 0.75 (g = 10 m/s², sin 53° = 0.8). The friction force on the block when the incline is at 30° and at 53° is respectively:", "options": ["13 N and 9 N", "10 N and 16 N", "13 N and 12 N", "10 N and 9 N"], "answer": 3, "explanation": "At 30°, tan 30° ≈ 0.58 < 0.75, so the block stays at rest and static friction equals mg sin 30° = 10 N (not μmg cos 30° ≈ 13 N). At 53°, tan 53° ≈ 1.33 > 0.75, so it slides and kinetic friction = 0.75 × 20 × 0.6 = 9 N.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-laws-of-motion-65", "question": "A smooth wedge has two faces inclined at 30° and 60° to the horizontal, meeting at a ridge carrying a light frictionless pulley. Blocks of 1 kg each rest on the two faces, joined by a string over the pulley (g = 10 m/s²). The acceleration of the blocks is:", "options": ["5(√3 − 1)/2 ≈ 1.83 m/s²", "3.66 m/s²", "5 m/s²", "2.5 m/s²"], "answer": 0, "explanation": "Net driving force = mg(sin 60° − sin 30°) = 10(0.866 − 0.5) ≈ 3.66 N, shared by a total mass of 2 kg: a ≈ 1.83 m/s², with the 60° block moving down. 3.66 m/s² forgets to divide by the total mass.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-laws-of-motion-66", "question": "A 0.5 kg ball strikes a smooth wall at 10 m/s with its velocity at 60° to the normal and rebounds elastically. If the contact lasts 0.05 s, the average force on the wall is:", "options": ["200 N", "173 N", "100 N", "50 N"], "answer": 2, "explanation": "Only the normal component reverses: Δp = 2mv cos 60° = 2 × 0.5 × 10 × 0.5 = 5 N s, so F = 5/0.05 = 100 N. 200 N treats the impact as head-on; 173 N uses sin 60°.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "phy-laws-of-motion-67", "question": "Assertion (A): It is easier to pull a heavy roller than to push it with a force applied at the same angle to the horizontal.\nReason (R): Pulling at an angle above the horizontal reduces the normal reaction and hence the friction, while pushing at an angle below the horizontal increases it.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A: when pulling, N = mg − F sin θ; when pushing, N = mg + F sin θ. The smaller normal reaction means less friction to overcome.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-laws-of-motion-68", "question": "Match the system (List I) with its acceleration (List II) (g = 10 m/s², sin 37° = 0.6).\nList I: (P) masses 3 kg and 2 kg on a light pulley (Atwood machine); (Q) block sliding down a smooth 53° incline; (R) block sliding down a 37° incline with μ = 0.25; (S) 1 kg block on a smooth table pulled by a 1 kg hanging mass over a pulley.\nList II: (1) 2 m/s²; (2) 4 m/s²; (3) 5 m/s²; (4) 8 m/s².", "options": ["P-1, Q-3, R-2, S-4", "P-2, Q-4, R-1, S-3", "P-3, Q-4, R-2, S-1", "P-1, Q-4, R-2, S-3"], "answer": 3, "explanation": "P: 10 × 1/5 = 2. Q: 10 sin 53° = 8. R: 10(0.6 − 0.25 × 0.8) = 4. S: 10 × 1/2 = 5. So P-1, Q-4, R-2, S-3.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-laws-of-motion-69", "question": "A coin placed 4 cm from the centre of a horizontal turntable just begins to slip when the turntable rotates at 60 rpm. If the turntable rotates at 30 rpm, the greatest distance from the centre at which the coin can stay without slipping is:", "options": ["8 cm", "16 cm", "2 cm", "4√2 cm"], "answer": 1, "explanation": "At the slipping limit μmg = mω²r, so ω²r is fixed. Halving ω makes r four times larger: 4 × 4 = 16 cm. 8 cm assumes r ∝ 1/ω.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "phy-laws-of-motion-70", "question": "A light frictionless pulley hangs from a spring balance. Masses of 3 kg and 1 kg are attached to the two ends of a light string passing over it and are released (g = 10 m/s²). While they move, the spring balance reads:", "options": ["40 N", "20 N", "30 N", "15 N"], "answer": 2, "explanation": "a = 10 × 2/4 = 5 m/s², and T = 2m₁m₂g/(m₁ + m₂) = 2 × 3 × 1 × 10/4 = 15 N. The balance supports 2T = 30 N, less than the 40 N total weight because the centre of mass is accelerating downward. 15 N is the string tension alone.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"phy-laws-of-motion-71","question":"A small bob hangs by a string from the roof of a car that goes round a level circular track of radius 10 m at a constant 10 m/s (g = 10 m/s²). In the steady state the string makes an angle with the vertical of:","options":["45°","60°","30°","0°"],"answer":0,"explanation":"In the car's frame the bob feels mv²/r outward: tan θ = v²/(rg) = 100/100 = 1, so θ = 45°, tilted away from the centre. Zero would be true only for a car moving in a straight line at constant speed.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-laws-of-motion-72","question":"A 1 kg particle moves along the x-axis with velocity v = 2x (SI units). The net force on it when it is at x = 3 m is:","options":["2 N","12 N","6 N","24 N"],"answer":1,"explanation":"a = v dv/dx = (2x)(2) = 4x, so at x = 3 m, a = 12 m/s² and F = 12 N. Taking dv/dx = 2 as the acceleration gives 2 N; using v itself gives 6 N.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-laws-of-motion-73","question":"A 2 kg body at rest is acted on by a force of +10 N for 2 s, followed by a force of −5 N for the next 2 s. Its velocity at the end of the 4 s is:","options":["15 m/s","10 m/s","5 m/s","7.5 m/s"],"answer":2,"explanation":"Net impulse = 10 × 2 − 5 × 2 = 10 N s, so v = 10/2 = 5 m/s in the positive direction. Adding the magnitudes of the impulses (30 N s) gives 15 m/s.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-laws-of-motion-74","question":"Block A of mass m is tied to the ceiling by a string, and block B of mass 2m hangs from A by a light spring; the system is at rest. Immediately after the string above A is cut, the accelerations of A and B are:","options":["g downward and g downward","3g downward and g downward","g downward and zero","3g downward and zero"],"answer":3,"explanation":"Before the cut the spring holds B with force 2mg. The spring cannot change its length instantly, so just after the cut it still pulls A down with 2mg and B up with 2mg. A: (mg + 2mg)/m = 3g downward; B: 2mg − 2mg = 0. Saying both fall at g treats the spring like a string.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-laws-of-motion-75","question":"A 2 kg block slides at 10 m/s on a smooth floor. It is joined by a slack inextensible string to a 3 kg block at rest. When the string becomes taut the blocks move on together. The impulse delivered by the string to the 3 kg block is:","options":["12 N s","20 N s","30 N s","6 N s"],"answer":0,"explanation":"Momentum is conserved during the jerk: 2 × 10 = 5v, so v = 4 m/s. Impulse on the 3 kg block = 3 × 4 = 12 N s (and the 2 kg block loses 2 × 6 = 12 N s, as it must). 20 N s is the whole initial momentum.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-laws-of-motion-76","question":"A thin ring of mass 2 kg and radius 0.5 m spins about its axis at 10 rad/s in gravity-free space. The tension in the ring is about:","options":["100 N","15.9 N","31.8 N","50 N"],"answer":1,"explanation":"A small element subtending dθ needs centripetal force (m dθ/2π)ω²R, supplied by the two tensions: T dθ = (m/2π)ω²R dθ, so T = mω²R/(2π) = 2 × 100 × 0.5/(2π) ≈ 15.9 N. 100 N is mω²R for the whole ring; 31.8 N uses π instead of 2π.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-laws-of-motion-77","question":"Blocks of 2 kg and 3 kg on a smooth floor are joined by a light spring. A constant horizontal force of 20 N pulls the 3 kg block away from the 2 kg block. At an instant when the 2 kg block has an acceleration of 2 m/s², the acceleration of the 3 kg block is:","options":["20/3 m/s²","4 m/s²","16/3 m/s²","2 m/s²"],"answer":2,"explanation":"The only horizontal force on the 2 kg block is the spring: F_s = 2 × 2 = 4 N. For the 3 kg block: 20 − 4 = 3a, so a = 16/3 ≈ 5.33 m/s². 4 m/s² is the centre-of-mass acceleration, which only equals each block's acceleration when the spring length stops changing.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-laws-of-motion-78","question":"A small bead can slide on a smooth vertical circular ring of radius 0.5 m that rotates about its vertical diameter at 4 rad/s (g = 10 m/s²). In the bead's stable position, the angle between the radius to the bead and the downward vertical is:","options":["cos⁻¹(0.8)","cos⁻¹(5/8)","90°","0° (the bead stays at the bottom)"],"answer":3,"explanation":"Off the bottom, equilibrium needs cos θ = g/(ω²R) = 10/(16 × 0.5) = 1.25, which is impossible. Below the critical speed √(g/R) = √20 ≈ 4.47 rad/s, the only stable position is the lowest point. cos⁻¹(0.8) comes from inverting the ratio.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-laws-of-motion-79","question":"A block slides up a rough plane inclined at 45° (μ = 0.5), stops, and slides back to its starting point. The ratio of the time taken to come down to the time taken to go up is:","options":["√3","3","√2","1/√3"],"answer":0,"explanation":"Going up: a = g(sin θ + μ cos θ) = 1.5 g/√2; coming down: a = g(sin θ − μ cos θ) = 0.5 g/√2. For the same distance t ∝ 1/√a, so t_down/t_up = √(1.5/0.5) = √3. It does slide back, since tan 45° = 1 > μ. 3 is the ratio of the accelerations without the square root.","difficulty":"hard","source":"JEE Main pattern"},
  {"id": "phy-laws-of-motion-80", "question": "A 2 kg block is placed on the smooth 45° face of a 4 kg wedge, which itself rests on a smooth horizontal floor. When the block is released, the normal force between the block and the wedge is:", "options": ["10√2 N", "8√2 N", "20 N", "4√2 N"], "answer": 1, "explanation": "With the wedge free, N = Mmg cos θ/(M + m sin²θ) = 4 × 2 × 10 × (1/√2)/(4 + 1) = 8√2 ≈ 11.3 N. The fixed-wedge value mg cos θ = 10√2 N is wrong because the wedge moves away from the block.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-laws-of-motion-81", "question": "A 2 kg block is placed on the smooth 45° face of a 4 kg wedge, which rests on a smooth horizontal floor, and the system is released from rest (g = 10 m/s²). The acceleration of the wedge is:", "options": ["2.5 m/s²", "5 m/s²", "2 m/s²", "5/3 m/s²"], "answer": 2, "explanation": "A = mg sin θ cos θ/(M + m sin²θ) = 2 × 10 × 0.5/(4 + 2 × 0.5) = 10/5 = 2 m/s². Using N = mg cos θ (as for a fixed wedge) gives mg sin θ cos θ/M = 2.5 m/s²; 5/3 m/s² treats block and wedge as moving together.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"phy-laws-of-motion-82","question":"A 2 kg block lies on a 4 kg block, which rests on a rough floor. The coefficient of friction is 0.5 between the blocks and 0.1 between the lower block and the floor. A horizontal force of 15 N is applied to the upper block (g = 10 m/s²). The acceleration of the lower block is:","options":["0","1.5 m/s²","2.5 m/s²","1.0 m/s²"],"answer":3,"explanation":"If they moved together: a = (15 − 0.1 × 60)/6 = 1.5 m/s², which needs friction 15 − 2 × 1.5 = 12 N on the upper block, more than the 10 N available. So they slip: the upper block gets (15 − 10)/2 = 2.5 m/s², and the lower block (10 − 6)/4 = 1.0 m/s². 1.5 m/s² misses the slipping check.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-laws-of-motion-83", "question": "A uniform chain of mass 2 kg is held vertically with its lower end just touching the pan of a weighing machine and is then released. When half of the chain has fallen onto the pan, the machine reads a force of (g = 10 m/s²):", "options": ["30 N", "10 N", "20 N", "15 N"], "answer": 0, "explanation": "When a length x has fallen, the speed of the falling links is √(2gx), and stopping them needs a force λv² = λ(2gx) = 2 × (weight already on the pan). Reading = weight on pan + 2 × weight on pan = 3λgx = 3 × 1 × 10 = 30 N. 10 N counts only the weight resting on the pan.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"phy-laws-of-motion-84","question":"A small block rests on the rough face of a wedge inclined at 37° (μ = 0.5, sin 37° = 0.6). The wedge is given a horizontal acceleration a towards the side on which the block rests, so that the face presses harder into the block (g = 10 m/s²). The largest a for which the block does not slide relative to the wedge is:","options":["7.5 m/s²","20 m/s²","1.8 m/s²","10 m/s²"],"answer":1,"explanation":"At the upper limit the block tends to slide up, so friction acts down the slope: N sin θ + f cos θ = ma, N cos θ − f sin θ = mg, f = μN. a_max = g(sin θ + μ cos θ)/(cos θ − μ sin θ) = 10 × 1.0/0.5 = 20 m/s². 7.5 m/s² (g tan θ) is the smooth-face value, and 1.8 m/s² is the lower limit, below which the block slides down.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-laws-of-motion-85","question":"A coin is placed 1 m from the centre of a horizontal turntable (μ = 0.5 between them). The turntable starts from rest with a constant angular acceleration of 3 rad/s² (g = 10 m/s²). The coin begins to slip after:","options":["√5/3 s","1/3 s","2/3 s","√5 s"],"answer":2,"explanation":"Friction must supply both a_t = rα = 3 m/s² and a_c = rω² = 9t². Slipping starts when √(3² + (9t²)²) = μg = 5, so 9t² = 4 and t = 2/3 s. Ignoring the tangential part (9t² = 5) gives √5/3 s, too late.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "phy-laws-of-motion-86", "question": "How many of the following statements are correct?\n(A) Kinetic friction can only slow bodies down; it can never be the force that speeds a body up.\n(B) For a car going round a level curve at constant speed, the friction force from the road on the tyres points towards the centre of the curve.\n(C) Static friction on a body always opposes the body's motion relative to the ground.\n(D) The coefficient of static friction between two surfaces can be greater than 1.", "options": ["Only one", "Only three", "All four", "Only two"], "answer": 3, "explanation": "B and D are correct. A is wrong: a block dropped onto a moving conveyor belt is speeded up by kinetic friction. C is wrong: friction opposes relative motion (or its tendency) between the surfaces in contact, not motion relative to the ground; static friction is what drives a walking person or a box on an accelerating truck forward.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-laws-of-motion-87","question":"A 5 kg block rests on a rough plane inclined at 37° (μ = 0.75, sin 37° = 0.6, g = 10 m/s²). The least force that can drag it up the plane, and the direction in which it must be applied, are:","options":["60 N parallel to the incline","36 N at 37° above the surface of the incline","48 N parallel to the incline","48 N at 37° above the surface of the incline"],"answer":3,"explanation":"Pulling at angle φ above the incline: F(cos φ + μ sin φ) = mg(sin θ + μ cos θ). F is least when tan φ = μ = 0.75 (φ = 37°): F_min = mg(sin θ + μ cos θ)/√(1 + μ²) = 50 × 1.2/1.25 = 48 N. Pulling parallel to the incline needs 60 N.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-laws-of-motion-88", "question": "Two 2 kg blocks joined by a light string slide down a 37° incline with the string parallel to the slope (sin 37° = 0.6, g = 10 m/s²). The lower block has μ = 0.25 and the upper block μ = 0.5. The tension in the string is:", "options": ["2 N", "0", "4 N", "1 N"], "answer": 0, "explanation": "Alone, the lower block would accelerate at 6 − 2 = 4 m/s² and the upper at 6 − 4 = 2 m/s², so the string goes taut. Together: a = 6 − 10 × 0.8 × (0.25 + 0.5)/2 = 3 m/s². Lower block: 12 − 4 − T = 2 × 3, so T = 2 N. Zero would be right only if the blocks were the other way round (the slower block below).", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-laws-of-motion-89","question":"A 60 kg man sits in a 20 kg chair hung from a rope that passes over a light frictionless pulley fixed to the ceiling; he holds the other end of the rope and pulls himself and the chair upward with an acceleration of 2 m/s² (g = 10 m/s²). The force between the man and the chair is:","options":["480 N","240 N","720 N","120 N"],"answer":1,"explanation":"Both rope segments pull the system up: 2T − 800 = 80 × 2, so T = 480 N. For the man: T + N − 600 = 60 × 2, so N = 240 N. 480 N is his pull on the rope.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-laws-of-motion-90", "question": "Block A (1 kg) lies on block B (2 kg), which rests on a smooth floor. A light string tied to A passes round a smooth pulley fixed to a wall and is tied to B, both parts of the string being horizontal. The coefficient of friction between A and B is 0.5. The horizontal force that must pull B away from the wall to give it an acceleration of 1 m/s² is (g = 10 m/s²):", "options": ["8 N", "3 N", "13 N", "18 N"], "answer": 2, "explanation": "A moves towards the wall at 1 m/s², and kinetic friction (5 N) acts on A away from the wall and on B towards the wall. A: T − 5 = 1 × 1, so T = 6 N. B: F − T − 5 = 2 × 1, so F = 13 N. Counting friction only once (on B) gives 8 N, which overlooks friction acting on A as well.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "phy-laws-of-motion-91", "question": "Assertion (A): A block resting on a rough incline stays at rest when the incline is placed in a lift that accelerates upward.\nReason (R): In the lift's frame both the normal force and the component of the effective weight along the incline are scaled by the same factor (g + a)/g.", "options": ["Both A and R are true, but R is not the correct explanation of A", "A is true but R is false", "Both A and R are true, and R is the correct explanation of A", "A is false but R is true"], "answer": 2, "explanation": "In the lift's frame the effective gravity is g + a. The force down the slope, m(g + a) sin θ, and the limiting friction, μm(g + a) cos θ, are both scaled up by the same factor, so the condition tan θ ≤ μ is unchanged. R is exactly why A holds.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-laws-of-motion-92","question":"A 1 kg block on a smooth horizontal disc is tied by a light spring (natural length 0.4 m, k = 100 N/m) to a peg at the centre. The disc rotates at 5 rad/s and the block turns with it without sliding. The extension of the spring is:","options":["20 cm","10 cm","13.3 cm","6.7 cm"],"answer":2,"explanation":"The spring supplies the centripetal force at the stretched radius r: k(r − 0.4) = mω²r, so 100r − 40 = 25r, r = 0.533 m, and the extension is 0.133 m = 13.3 cm. Using the natural length as the radius (25 × 0.4/100) gives 10 cm.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-laws-of-motion-93", "question": "A block is released from rest at the top of a long plane inclined at 45°. The coefficient of friction increases with the distance x travelled down the slope as μ = 0.5x (x in metres). The block comes to rest after travelling:", "options": ["2 m", "1 m", "8 m", "4 m"], "answer": 3, "explanation": "a = g(sin θ − 0.5x cos θ), which is SHM-like about x = 2 m, where a = 0. Starting from rest at x = 0, it stops symmetrically at x = 4 m (check with energy: g sin θ · x = g cos θ · 0.25x², so x = 4 m). It stays there, since μ = 2 > tan 45°. 2 m is where its speed is greatest.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"phy-laws-of-motion-94","question":"A light rope passes over a light frictionless pulley. A 20 kg monkey holds one end, and a 20 kg block rests on the floor tied to the other end. The monkey climbs with an acceleration of 2 m/s² relative to the rope (g = 10 m/s²). The tension in the rope is:","options":["220 N","240 N","200 N","400 N"],"answer":0,"explanation":"Let both rise with accelerations a_m and a_b (ground frame). The rope on the monkey's side moves down at a_b, so a_m + a_b = 2. T − 200 = 20a_m and T − 200 = 20a_b, so a_m = a_b = 1 m/s² and T = 220 N. 240 N assumes the monkey accelerates at 2 m/s² relative to the ground.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-laws-of-motion-95", "question": "A 1 kg ball falls from rest through air that exerts a drag force F = 2v (SI units, v = speed; g = 10 m/s²). The time it takes to reach half of its terminal speed is about:", "options": ["0.25 s", "0.35 s", "0.50 s", "0.69 s"], "answer": 1, "explanation": "m dv/dt = mg − kv gives v = v_T(1 − e^(−kt/m)) with v_T = mg/k = 5 m/s. Half of v_T is reached when e^(−2t) = 1/2: t = (ln 2)/2 ≈ 0.35 s. Ignoring drag (2.5/10) gives 0.25 s; m/k = 0.5 s is the time constant, not the half-speed time.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-laws-of-motion-96","question":"A horse pulls a cart and both start moving forward from rest on a level road. Which statement correctly explains why the horse–cart system accelerates?","options":["The horse's weight provides the forward force","The pull of the horse on the cart exceeds the pull of the cart on the horse","Action and reaction cancel only when the bodies are at rest","The forward friction of the road on the horse's hooves exceeds the backward friction of the road on the cart's wheels"],"answer":3,"explanation":"The horse–cart pull pair are third-law partners: always equal and opposite, and internal to the system. The system accelerates only because of external horizontal forces: the road pushes the horse forward (friction on hooves) more than it resists the cart.","difficulty":"easy","source":"JEE Main"},
  {"id":"phy-laws-of-motion-97","question":"A 4 kg block lies on a smooth horizontal table. A light string from it passes over a smooth pulley at the table's edge, goes down under a light movable pulley carrying a 4 kg block, and then up to a hook fixed under the table, the two strands supporting the movable pulley being vertical (g = 10 m/s²). The acceleration of the hanging 4 kg block is:","options":["5 m/s²","4 m/s²","2 m/s²","10/3 m/s²"],"answer":2,"explanation":"Constraint: if the table block moves x, the movable pulley drops x/2, so a₁ = 2a₂. Table block: T = 4a₁ = 8a₂. Hanging block: 40 − 2T = 4a₂, giving 40 = 20a₂, so a₂ = 2 m/s² (and the table block accelerates at 4 m/s²).","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-laws-of-motion-98","question":"A 2 kg block rests on a 4 kg block that lies on a smooth floor; the coefficient of friction between the blocks is 0.4. A horizontal force F = 2t newton (t in seconds) is applied to the UPPER block, starting at t = 0 (g = 10 m/s²). The blocks begin to slide relative to each other at:","options":["t = 4 s","t = 6 s","t = 3 s","t = 12 s"],"answer":1,"explanation":"The lower block is driven only by friction, so its largest possible acceleration is 0.4 × 20/4 = 2 m/s². Moving together, F = 6a, so slipping starts when F = 6 × 2 = 12 N, i.e. at t = 6 s. (t = 4 s wrongly sets F equal to the friction limit of 8 N.)","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-laws-of-motion-99","question":"A curve of radius 30 m is banked at 37° (sin 37° = 0.6), and the coefficient of friction between tyres and road is 0.5 (g = 10 m/s²). The MINIMUM speed at which a car can go round the curve without slipping down the bank is about:","options":["7.4 m/s","15 m/s","24.5 m/s","zero, as the car can even stay parked on the bank"],"answer":0,"explanation":"Since tan 37° = 0.75 > μ, a parked car would slide down, so a minimum speed exists. With friction acting up the bank: v² = rg(sin θ − μ cos θ)/(cos θ + μ sin θ) = 300 × 0.2/1.1 ≈ 54.5, so v ≈ 7.4 m/s. (15 m/s is the friction-free speed and 24.5 m/s the maximum.)","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-laws-of-motion-100","question":"A small ball moves in a horizontal circle on the smooth inner surface of a fixed hemispherical bowl of radius 0.5 m, at a height of 0.4 m above the lowest point of the bowl (g = 10 m/s²). Its angular speed is:","options":["10 rad/s","5 rad/s","√50 rad/s","2√5 rad/s"],"answer":0,"explanation":"The normal force points to the bowl's centre. If the radius to the ball makes angle θ with the vertical: N cos θ = mg and N sin θ = mω²R sin θ, so ω² = g/(R cos θ). The ball is R cos θ = 0.5 − 0.4 = 0.1 m below the centre, so ω² = 100 and ω = 10 rad/s, independent of mass.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-laws-of-motion-101","question":"A 0.2 kg ball moving at 10 m/s strikes a wall head-on. The force exerted by the wall rises linearly from zero to 150 N and falls linearly back to zero, the whole contact lasting 0.04 s. After the impact the ball moves:","options":["at 5 m/s towards the wall","at 15 m/s away from the wall","at 10 m/s away from the wall","at 5 m/s away from the wall"],"answer":3,"explanation":"Impulse = area of the triangular F–t graph = ½ × 150 × 0.04 = 3 N s, directed away from the wall. Final momentum = −0.2 × 10 + 3 = +1 kg m/s, so the ball rebounds at 1/0.2 = 5 m/s.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-laws-of-motion-102","question":"A trolley full of sand moves on a smooth level track under a constant horizontal force F. Sand leaks out vertically (relative to the trolley) through a hole in its floor at a constant rate. Which statement is correct?","options":["The acceleration decreases, because the escaping sand carries momentum backward","The acceleration is constant, because F is constant","The trolley's acceleration increases with time, since F acts on an ever-smaller mass","The trolley moves at constant velocity once leaking starts"],"answer":2,"explanation":"Sand leaving with zero relative velocity carries away exactly its share of momentum and exerts no thrust on the trolley. So F = m(t)·a for the remaining mass, with m(t) = m₀ − μt decreasing, and a = F/(m₀ − μt) increases with time.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-laws-of-motion-103","question":"A 5 kg block rests on a rough plane inclined at 37° (μ = 0.5, sin 37° = 0.6, g = 10 m/s²). A HORIZONTAL force F, in the vertical plane of the line of greatest slope and pushing towards the incline, holds it at rest. The range of F for which the block stays at rest is:","options":["10 N ≤ F ≤ 50 N","9.1 N ≤ F ≤ 100 N","9.1 N ≤ F ≤ 45.5 N","0 ≤ F ≤ 100 N"],"answer":1,"explanation":"F has components F cos θ up the slope and F sin θ into the slope, which also raises the friction limit. About to slide down: F(cos θ + μ sin θ) = mg(sin θ − μ cos θ), so F = 50 × 0.2/1.1 ≈ 9.1 N. About to slide up: F(cos θ − μ sin θ) = mg(sin θ + μ cos θ), so F = 50 × 1/0.5 = 100 N.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-laws-of-motion-104","question":"A 10 kg crate rests on a floor with μ = 0.75 (g = 10 m/s²). A worker pushes it with a force F directed 53° BELOW the horizontal (cos 53° = 0.6). The smallest F that starts the crate sliding is:","options":["125 N","none: it cannot be made to slide, however large F is","75 N","100 N"],"answer":1,"explanation":"Horizontal push = 0.6F. Maximum friction = μ(mg + 0.8F) = 75 + 0.6F. Since 0.6F < 75 + 0.6F for every F, the push can never overcome friction: the crate 'jams'. This happens whenever tan(angle below horizontal) ≥ 1/μ, here tan 53° = 4/3 = 1/0.75.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-laws-of-motion-105","question":"Masses of 3 kg and 2 kg hang from a light string over a light frictionless pulley fixed to the ceiling of a lift that accelerates upward at 2 m/s² (g = 10 m/s²). The tension in the string is:","options":["28.8 N","24 N","36 N","31.2 N"],"answer":0,"explanation":"In the lift frame, effective gravity is g + a = 12 m/s². For an Atwood machine T = 2m₁m₂g_eff/(m₁ + m₂) = 2 × 3 × 2 × 12/5 = 28.8 N. Using g = 10 m/s² alone gives the 24 N trap.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-laws-of-motion-106","question":"A 1 kg bob hangs by a string from the roof of a van that is accelerating at 5 m/s² UP a straight road inclined at 30° to the horizontal (g = 10 m/s²). With the bob at rest relative to the van, the tension in the string is about:","options":["8.7 N","15 N","11.2 N","13.2 N"],"answer":3,"explanation":"In the van's frame the bob feels g and a pseudo-acceleration −a. The effective gravity is g − a. With a at 30° above the horizontal: |g − a|² = g² + a² − 2g·a = 100 + 25 + 2 × 10 × 5 × sin 30° = 175. So T = m√175 = 5√7 ≈ 13.2 N.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-laws-of-motion-107","question":"A motorcyclist rides round the inside of a vertical cylindrical 'well' of radius 5 m with the wheels on the wall. The coefficient of friction between tyres and wall is 0.5 (g = 10 m/s²). The minimum speed for which he does not slide down is:","options":["7.1 m/s","5 m/s","10 m/s","14.1 m/s"],"answer":2,"explanation":"The wall's normal force supplies the centripetal force: N = mv²/R. Friction must hold the weight: μN ≥ mg, so v² ≥ gR/μ = 10 × 5/0.5 = 100 and v ≥ 10 m/s, independent of mass.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-laws-of-motion-108","question":"A uniform rope of mass 2 kg and length 1 m lies on a smooth horizontal table and rotates about one end at 4 rad/s. The tension in the rope at its midpoint is:","options":["8 N","16 N","12 N","24 N"],"answer":2,"explanation":"The tension at distance x from the pivot provides the centripetal force for the part beyond x: T(x) = ∫ₓᴸ (M/L)ω²r dr = (M/L)ω²(L² − x²)/2. At x = L/2: T = 2 × 16 × (1 − 0.25)/2 = 12 N.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-laws-of-motion-109","question":"Two 2 kg blocks are placed in contact on a plane inclined at 37° (sin 37° = 0.6, g = 10 m/s²) and released. The lower block has μ = 0.75 with the plane; the upper block, touching it from above, has μ = 0.25. The force between the blocks while they slide is:","options":["8 N","4 N","zero","2 N"],"answer":1,"explanation":"Alone, the lower block would just stay at rest (12 N down-slope vs 12 N friction) while the upper one would accelerate at 4 m/s², so they move together. Together: a = (24 − 12 − 4)/4 = 2 m/s². For the lower block: 2 × 2 = 12 − 12 + N, so N = 4 N.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-laws-of-motion-110","question":"A body is pulled along a rough horizontal floor by a horizontal force that increases slowly and steadily from zero. Which description of the friction force versus applied force is correct?","options":["Friction first equals the applied force (a 45° line), reaches its limiting value, then drops slightly to a constant kinetic value","Friction is constant at μₖN from the start","Friction rises linearly forever with the applied force","Friction is zero until the body moves, then jumps to μₛN"],"answer":0,"explanation":"While the body is at rest, static friction exactly balances the applied force, so the graph is a 45° line up to μₛN. Once slipping begins, kinetic friction μₖN (slightly less than μₛN) acts, constant thereafter.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-laws-of-motion-111","question":"A 60 kg man stands on a weighing machine fixed to a trolley that runs freely down a smooth plane inclined at 30° (g = 10 m/s²). The man does not slip on the machine. The machine reads:","options":["600 N","520 N","300 N","450 N"],"answer":3,"explanation":"The man, trolley and machine all accelerate at g sin 30° down the slope. Its vertical component is g sin²30°, so mg − N = m g sin²θ and N = mg cos²θ = 600 × 0.75 = 450 N. (Friction from the machine supplies the horizontal component.)","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-laws-of-motion-112","question":"A light spring balance is held horizontally by two strings that pass over smooth fixed pulleys; a 3 kg mass hangs from one string and a 5 kg mass from the other (g = 10 m/s²). The system is released. The spring balance reads:","options":["80 N","30 N","50 N","37.5 N"],"answer":3,"explanation":"The balance is just a link in an Atwood system and reads the string tension. a = (5 − 3)g/8 = 2.5 m/s², and T = 3(g + a) = 3 × 12.5 = 37.5 N. It is neither 50 N nor the total 80 N.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-laws-of-motion-113","question":"A bead can slide freely on a smooth straight rod that rotates in a horizontal plane about one end at a constant 2 rad/s. The bead is released from rest relative to the rod at 0.5 m from the axis. Its speed RELATIVE TO THE ROD when it is 1 m from the axis is:","options":["2 m/s","1 m/s","√3 m/s","√2 m/s"],"answer":2,"explanation":"In the rotating frame the only radial force is the centrifugal mω²r (the rod's normal force is perpendicular to it). So r̈ = ω²r, and integrating ṙ dṙ = ω²r dr gives ṙ² = ω²(r² − r₀²) = 4(1 − 0.25) = 3, so ṙ = √3 m/s.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-laws-of-motion-114","question":"A simple pendulum's bob is released from rest with the string horizontal. At the instant the bob's acceleration is purely horizontal, the angle θ that the string makes with the vertical satisfies:","options":["cos θ = 1/3","cos θ = 1/√3","cos θ = 1/√2","cos θ = 2/3"],"answer":1,"explanation":"At angle θ from the vertical, v² = 2gL cos θ and T − mg cos θ = mv²/L, so T = 3mg cos θ. The vertical acceleration is zero when T cos θ = mg, i.e. 3 cos²θ = 1, giving cos θ = 1/√3.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-laws-of-motion-115","question":"A block takes twice as long to slide from rest down a rough plane inclined at 45° as it takes to slide the same distance down an identical smooth plane. The coefficient of kinetic friction is:","options":["0.75","0.5","0.25","0.8"],"answer":0,"explanation":"s = ½at², so for the same s, t² ∝ 1/a. Smooth: a = g sin 45°; rough: a = g(sin 45° − μ cos 45°). Ratio 4 = 1/(1 − μ), so μ = 1 − 1/n² = 0.75.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-laws-of-motion-116","question":"A box is gently placed on a horizontal conveyor belt moving at a constant 4 m/s. The coefficient of friction between box and belt is 0.2 (g = 10 m/s²). The length of the scuff mark the box leaves on the belt is:","options":["4 m","8 m","2 m","16 m"],"answer":0,"explanation":"Friction accelerates the box at μg = 2 m/s², so it reaches 4 m/s after 2 s, covering ½ × 2 × 4 = 4 m. The belt meanwhile moves 8 m, so the relative slip, and hence the mark, is 8 − 4 = 4 m (= v²/2μg).","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-laws-of-motion-117","question":"A 1 kg block on a rough horizontal turntable (μ = 0.5) is tied to a string that passes through a small smooth hole at the centre and supports a hanging 2 kg mass. The block is 0.5 m from the hole and turns with the table (g = 10 m/s²). For the hanging mass to stay at rest, the angular speed ω must satisfy:","options":["0 ≤ ω ≤ √50 rad/s","ω = √40 rad/s exactly","√20 rad/s ≤ ω ≤ √40 rad/s","√30 rad/s ≤ ω ≤ √50 rad/s"],"answer":3,"explanation":"Tension = 20 N. If ω is small, friction (up to 5 N) acts outward: 20 − 5 = 1 × ω² × 0.5, ω² = 30. If ω is large, friction acts inward: 20 + 5 = 0.5ω², ω² = 50. Without friction it would have to be exactly √40 rad/s.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-laws-of-motion-118","question":"A 1000 kg car drives at 10 m/s through the lowest point of a dip in the road, which is a circular arc of radius 20 m (g = 10 m/s²). The normal force on the car from the road there is:","options":["5000 N","10000 N","15000 N","20000 N"],"answer":2,"explanation":"At the bottom of a concave arc, N − mg = mv²/R, so N = 1000(10 + 100/20) = 15000 N. Passengers feel heavier, the opposite of the convex-hump case.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-laws-of-motion-119","question":"A horizontal water jet of cross-section 1 cm² and speed 10 m/s strikes a flat vertical plate head-on; the plate moves away from the nozzle at a steady 4 m/s and the water spreads out along the plate. Taking the density of water as 1000 kg/m³, the force on the plate is:","options":["10 N","3.6 N","6 N","19.6 N"],"answer":1,"explanation":"In the plate's frame, water arrives at v − u = 6 m/s, and the mass striking per second is ρA(v − u) (the plate runs away from the jet). Each kilogram loses 6 m/s of normal momentum, so F = ρA(v − u)² = 1000 × 10⁻⁴ × 36 = 3.6 N.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-laws-of-motion-120","question":"A cart of mass 8 kg on a smooth floor carries a smooth pulley at its front top edge. A 1 kg block on the cart's smooth horizontal top is tied by a string over the pulley to another 1 kg block hanging against the cart's smooth vertical front face (g = 10 m/s²). The horizontal force on the cart needed to keep both blocks at rest relative to the cart is:","options":["80 N","100 N","50 N","120 N"],"answer":1,"explanation":"The hanging block has no vertical acceleration, so T = mg = 10 N. That same tension is the only horizontal force on the top block, so its acceleration a = T/m = g = 10 m/s². The whole system (10 kg) moves with this acceleration: F = 10 × 10 = 100 N.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-laws-of-motion-121","question":"A string that can bear at most 30 N holds a 2 kg body from the ceiling of a lift (g = 10 m/s²). The largest upward acceleration of the lift for which the string does not break is:","options":["5 m/s²","15 m/s²","10 m/s²","2.5 m/s²"],"answer":0,"explanation":"T − mg = ma, so a = (30 − 20)/2 = 5 m/s². Downward accelerations reduce the tension, so they never threaten the string.","difficulty":"easy","source":"JEE Main"},
  {"id":"phy-laws-of-motion-122","question":"A 4 kg block hangs from one end of a light string passing over a fixed smooth pulley. The other end supports a light movable pulley, over which a second string carries 1 kg and 3 kg blocks (g = 10 m/s²). On release, the acceleration of the 4 kg block is:","options":["5/2 m/s² downward","zero, since 4 kg balances 1 kg + 3 kg","10/7 m/s² upward","10/7 m/s² downward"],"answer":3,"explanation":"Unequal masses on the lower pulley accelerate, so the lower string's tension is less than (1 + 3)g/2. Solving: T₂ = 15 + 1.5a₁ and 40 − 2T₂ = 4a₁, so a₁ = 10/7 m/s² with the 4 kg block going down. Equivalently, the lower pulley system behaves like a mass 4m₂m₃/(m₂ + m₃) = 3 kg.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-laws-of-motion-123","question":"A block on a smooth floor is pulled by a rope that passes over a small pulley fixed above the floor; a man at the other end pulls the rope in at 3 m/s. At the instant the rope makes 37° with the horizontal at the block (cos 37° = 0.8), the block's speed is:","options":["3 m/s","2.4 m/s","3.75 m/s","5 m/s"],"answer":2,"explanation":"The rope is inextensible, so the component of the block's velocity along the rope equals the rate at which rope is pulled in: v cos 37° = 3. Hence v = 3/0.8 = 3.75 m/s, more than the rope speed.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-laws-of-motion-124","question":"Block P rests on top of block Q, and Q is placed on a SMOOTH plane inclined at 30°; the contact between P and Q (parallel to the incline) is rough. The pair is released from rest. The friction force between P and Q is:","options":["m_P g sin 30°","μ m_P g cos 30°","zero, whatever the coefficient of friction","μ m_P g"],"answer":2,"explanation":"Assume no slipping: the pair slides down at g sin 30°. P alone needs a down-slope force m_P g sin 30°, which its own weight component already supplies exactly. So friction between the blocks is zero, and no tendency to slip ever arises.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-laws-of-motion-125","question":"A uniform 3 kg chain of length 3 m hangs over a small smooth peg, with 1 m on one side and 2 m on the other, and is released from rest (g = 10 m/s²; ignore the tiny length in contact with the peg). At that instant, the tension in the chain at the peg is:","options":["10 N","40/3 N","20 N","20/3 N"],"answer":1,"explanation":"The chain moves as one body: a = (2 − 1)g/3 = 10/3 m/s². For the 1 kg piece going up: T − 10 = 1 × 10/3, so T = 40/3 ≈ 13.3 N. Check with the 2 kg piece: 20 − 40/3 = 2 × 10/3.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-laws-of-motion-126","question":"A child sits in a closed car holding the string of a helium balloon, with the windows shut. The car accelerates forward from rest. Relative to the car, the balloon:","options":["tilts forward, in the direction of the acceleration","tilts backward, like a hanging pendulum bob","stays vertical","first tilts backward, then forward"],"answer":0,"explanation":"In the car's frame, effective gravity g_eff = g − a points down and backward. The air pressure gradient then pushes the denser air backward, and buoyancy acts opposite to g_eff, i.e. up and forward. The light balloon therefore leans forward while a hanging bob would lean backward.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-laws-of-motion-127","question":"A 3 kg block (μ = 0.4 with the floor) is pulled horizontally by a 30 N force, and drags a 2 kg block (μ = 0.2 with the floor) behind it by a light horizontal string (g = 10 m/s²). The tension in the string is:","options":["5.6 N","12 N","4 N","9.6 N"],"answer":3,"explanation":"Total friction = 0.2 × 20 + 0.4 × 30 = 16 N, so a = (30 − 16)/5 = 2.8 m/s². For the trailing block: T − 4 = 2 × 2.8, so T = 9.6 N. The 12 N answer ignores the unequal friction coefficients.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-laws-of-motion-128","question":"A bead threaded on a smooth vertical circular wire of radius 0.5 m is given a speed v at the lowest point (g = 10 m/s²). The minimum v for which it goes all the way round is:","options":["√5 m/s","5 m/s","√10 m/s","2√5 m/s"],"answer":3,"explanation":"Unlike a string, the wire can push either way, so the bead only needs to reach the top with speed just above zero. v² = 2g(2R) = 4gR = 20, so v = 2√5 ≈ 4.47 m/s. The string-pendulum result √(5gR) = 5 m/s does not apply.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
];

export default questions;
